import { ChartData } from 'pages/components/ChartWithCaption/types';
import { BrandPowerData } from 'pages/pillars/PortfolioBrand/BrandAnalysis/types';

const hasPairedVariations = (data: ChartData): boolean =>
  data.variation_caption?.variationsRows?.kpi?.data?.some(
    (row) => (row?.variationsGroup?.length ?? 0) > 1,
  ) ?? false;

export function applyCompetitorConfigs(
  content: BrandPowerData,
  currentYear: string,
) {
  if (!content) {
    return content;
  }

  const year = currentYear.slice(-2);

  Object.keys(content).forEach((key) => {
    const data = content[key];
    if (data) {
      const interleavedSingleDataset =
        data.datasets?.length === 1 && hasPairedVariations(data);

      data.datasets?.forEach((dataset, i) => {
        const newArr = [];
        dataset.data.forEach((_data, idx) => {
          const isCompetitorSeries = interleavedSingleDataset
            ? idx % 2 === 1
            : i === 1;

          if (String(data.labels[idx]).includes(year)) {
            newArr.push(
              isCompetitorSeries
                ? 'rgba(123, 145, 157, 1)'
                : 'rgba(209, 163, 60, 1)',
            );
          } else {
            newArr.push(
              isCompetitorSeries
                ? 'rgba(160, 174, 183, 1)'
                : 'rgba(232, 209, 157, 1)',
            );
          }
        });
        dataset.backgroundColor = newArr;
      });
      data.paddingTop = 20;
    }
  });

  return content;
}
